import{useEffect,useMemo,useState}from'react';import type{FormEvent}from'react';import{Activity,ArrowDownLeft,ArrowUpRight,BriefcaseBusiness,CalendarDays,Check,ChevronDown,ClipboardList,Clock3,Download,FileCheck2,FileText,Grid2X2,HardHat,LogOut,Menu,MessageCircle,Plus,Search,Settings,ShieldCheck,Users,Wallet,X,Receipt,MonitorCog,LoaderCircle}from'lucide-react';import{configured,supabase}from'./supabase';import{quotePdf,receiptPdf}from'./documents';
type Section='Dashboard'|'Clientes'|'Catálogo'|'Orçamentos'|'Ordens de serviço'|'Financeiro'|'Relatórios'|'Configurações';type Row=Record<string,any>;const nav:{name:Section;icon:any}[]=[{name:'Dashboard',icon:Grid2X2},{name:'Clientes',icon:Users},{name:'Catálogo',icon:MonitorCog},{name:'Orçamentos',icon:FileText},{name:'Ordens de serviço',icon:HardHat},{name:'Financeiro',icon:Wallet},{name:'Relatórios',icon:Activity},{name:'Configurações',icon:Settings}];
const normalizeBrazilPhone=(value:any)=>{const raw=String(value||'').trim();if(!raw)return null;const digits=raw.replace(/\D/g,'');if(raw.startsWith('+'))return`+${digits}`;return digits.startsWith('55')?`+${digits}`:`+55${digits}`};const phoneForWhatsApp=(value:any)=>String(normalizeBrazilPhone(value)||'').replace(/\D/g,'');const money=(x:any)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(x||0));const dt=(x:any)=>x?new Date(x).toLocaleDateString('pt-BR'):'—';const slug=(s:string)=>s.toLowerCase().replaceAll(' ','_');const stateName=(s:string)=>({open:'Aberto',review:'Em análise',awaiting_quote:'Aguardando orçamento',quote_sent:'Orçamento enviado',awaiting_approval:'Aguardando aprovação',approved:'Aprovado',scheduled:'Agendado',in_progress:'Em execução',completed:'Concluído',closed:'Encerrado',cancelled:'Cancelado',quote_declined:'Recusado',awaiting_payment:'Aguardando pagamento',draft:'Rascunho',sent:'Enviado',declined:'Recusado',change_requested:'Alteração solicitada',expired:'Expirado'} as any)[s]||s;
export default function App(){const[session,setSession]=useState<any>(null),[ready,setReady]=useState(false),[section,setSection]=useState<Section>('Dashboard'),[data,setData]=useState<Record<string,Row[]>>({}),[company,setCompany]=useState<Row|null>(null),[modal,setModal]=useState(''),[busy,setBusy]=useState(false),[err,setErr]=useState(''),[ok,setOk]=useState(''),[query,setQuery]=useState(''),[mobile,setMobile]=useState(false),[selected,setSelected]=useState<Row|null>(null),[editing,setEditing]=useState<Row|null>(null),[cardFeeRate,setCardFeeRate]=useState('0'),[quotePreviewTick,setQuotePreviewTick]=useState(0),[quoteStatusFilter,setQuoteStatusFilter]=useState('all'),[recovery,setRecovery]=useState(false),[quoteItems,setQuoteItems]=useState<Row[]>([{description:'',quantity:'1',unit_price:''}]);
useEffect(()=>{if(!supabase){setReady(true);return}supabase.auth.getSession().then(({data:{session}})=>{setSession(session);setReady(true)});const{data:{subscription}}=supabase.auth.onAuthStateChange((event,s)=>{setSession(s);if(event==='PASSWORD_RECOVERY')setRecovery(true);setReady(true)});return()=>subscription.unsubscribe()},[]);
const refresh=async()=>{if(!supabase||!session)return;const [c,clients,services,quotes,qv,orders,payments,cats]=await Promise.all([supabase.from('companies').select('*').limit(1).maybeSingle(),supabase.from('clients').select('*').order('created_at',{ascending:false}),supabase.from('services').select('*').order('name'),supabase.from('quotes').select('*,clients!quotes_client_id_fkey(name)').order('created_at',{ascending:false}),supabase.from('quote_versions').select('*'),supabase.from('work_orders').select('*,clients!work_orders_client_id_fkey(name),quotes!work_orders_quote_id_fkey(quote_no)').order('created_at',{ascending:false}),supabase.from('payments').select('*,clients!payments_client_id_fkey(name)').order('created_at',{ascending:false}),supabase.from('service_categories').select('*').order('sort_order')]);for(const x of[clients,services,quotes,qv,orders,payments,cats])if(x.error){setErr(x.error.message);return}setCompany(c.data);setData({clients:clients.data||[],services:services.data||[],quotes:quotes.data||[],versions:qv.data||[],orders:orders.data||[],payments:payments.data||[],categories:cats.data||[]})};useEffect(()=>{refresh()},[session]);useEffect(()=>{if(session&&section==='Ordens de serviço')void refresh()},[session,section]);useEffect(()=>{if(!session||section!=='Ordens de serviço')return;const interval=window.setInterval(()=>void refresh(),20000);return()=>window.clearInterval(interval)},[session,section]);
const notify=(s:string)=>{setOk(s);setTimeout(()=>setOk(''),4500)};const quoteMessage=(q:Row,version:Row,client:Row,link:string)=>`Olá, ${client.name}!\n\nA PH SERVICE FORTAL preparou seu orçamento nº ORC-${String(q.quote_no).padStart(5,'0')}.\n\nServiço: ${version?.description||version?.items?.map((i:Row)=>i.description).join(', ')||'Conforme PDF'}\nValor total: ${money(version?.total)}\nPrazo estimado: ${version?.estimated_duration||'A combinar'}\nForma de pagamento: ${{pix:'Pix',cash:'Dinheiro',debit:'Cartão de débito',credit:'Cartão de crédito',transfer:'Transferência',installment:'Parcelado no cartão',entry_balance:'Entrada + saldo'}[version?.payment_method as string]||'A combinar'}\nValidade: ${dt(q.valid_until)}\n\nPara conferir e aprovar, acesse o link seguro:\n${link}\n\nObrigado pela confiança!\nPH SERVICE FORTAL`;const savePdf=(file:File)=>{const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};const sendFileToClient=async(file:File,client:Row,message:string)=>{if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:file.name,text:message});notify('Selecione o WhatsApp e o cliente no menu de compartilhamento para enviar o PDF.');return}catch(e:any){if(e?.name==='AbortError')return}}savePdf(file);const phone=phoneForWhatsApp(client?.phone);if(phone)window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message+'\n\nO PDF foi baixado. Anexe o arquivo antes de enviar.')}`,'_blank','noopener,noreferrer');notify(phone?'PDF baixado e WhatsApp aberto. Anexe o arquivo à conversa e confirme o envio.':'PDF baixado. Cadastre o WhatsApp do cliente para abrir a conversa.')};const downloadQuotePdf=(q:Row)=>{const client=data.clients?.find(c=>c.id===q.client_id)||{};const version=data.versions?.find(x=>x.quote_id===q.id&&x.version===q.current_version)||{};savePdf(quotePdf(q,version,client,company||undefined));notify('PDF do orçamento baixado.')};const shareQuote=async(q:Row)=>{if(!supabase)return;const client=data.clients?.find(c=>c.id===q.client_id);if(!client?.phone){setErr('Cadastre o telefone do cliente. O DDI +55 será incluído automaticamente.');return}const version=data.versions?.find(x=>x.quote_id===q.id&&x.version===q.current_version)||{};setBusy(true);try{const{data:token,error}=await supabase.rpc('issue_quote_approval_link',{p_quote_id:q.id,p_days:14});if(error)throw error;const link=`${window.location.origin}/aprovar/${token}`;await sendFileToClient(quotePdf(q,version,client,company||undefined),client,quoteMessage(q,version,client,link))}catch(e:any){setErr(e.message||'Não foi possível preparar o envio do orçamento.')}finally{setBusy(false)}};const buildReceiptPdf=(payment:Row)=>{if(payment.status!=='received'){setErr('Recibo disponível após registrar o pagamento como recebido.');return null}const client=data.clients?.find(c=>c.id===payment.client_id)||{};const quote=data.quotes?.find(q=>q.id===payment.quote_id);const version=quote?data.versions?.find(v=>v.quote_id===quote.id&&v.version===quote.current_version):undefined;const serviceDetail=(version?.items||[]).length||version?.description||payment.notes;if(!serviceDetail){setErr('Para discriminar o serviço, vincule o pagamento a um orçamento ou preencha a observação do lançamento.');return null}return receiptPdf(payment,quote,version,client,company||undefined)};const downloadReceipt=(payment:Row)=>{const file=buildReceiptPdf(payment);if(!file)return;savePdf(file);notify('Recibo PDF baixado. Você pode enviá-lo depois.')};const shareReceipt=async(payment:Row)=>{const file=buildReceiptPdf(payment);if(!file)return;const client=data.clients?.find(c=>c.id===payment.client_id)||{};const message=`Olá, ${client.name||'cliente'}! Segue o recibo do pagamento de ${money(payment.amount)}, recebido em ${dt(payment.paid_at)} por ${({pix:'Pix',cash:'Dinheiro',debit:'Cartão de débito',credit:'Cartão de crédito',transfer:'Transferência bancária',installment:'Parcelado',other:'Outro'} as any)[payment.method]||payment.method}. O PDF contém a discriminação do serviço. PH SERVICE FORTAL.`;await sendFileToClient(file,client,message)};const sendReceiptToWhatsApp=(payment:Row)=>{const file=buildReceiptPdf(payment);if(!file)return;const client=data.clients?.find(c=>c.id===payment.client_id)||{};const phone=phoneForWhatsApp(client.phone);if(!phone){setErr('Cadastre o telefone/WhatsApp do cliente antes de enviar.');return}const message=`Olá, ${client.name||'cliente'}! Segue o recibo do pagamento de ${money(payment.amount)}, recebido em ${dt(payment.paid_at)} por ${({pix:'Pix',cash:'Dinheiro',debit:'Cartão de débito',credit:'Cartão de crédito',transfer:'Transferência bancária',installment:'Parcelado',other:'Outro'} as any)[payment.method]||payment.method}. O PDF foi baixado; anexe-o a esta conversa antes de enviar. PH SERVICE FORTAL.`;savePdf(file);window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');notify('Recibo PDF baixado e conversa do WhatsApp do cliente aberta. Anexe o PDF para concluir o envio.') };const approveQuoteManually=async(q:Row)=>{if(!supabase)return;const client=data.clients?.find(c=>c.id===q.client_id);const name=window.prompt('Nome da pessoa cliente que confirmou o aceite:',client?.name||'')?.trim();if(!name)return;if(name.length<2){setErr('Informe o nome de quem aprovou o orçamento.');return}const evidence=window.prompt('Como o cliente confirmou o aceite? Registre uma evidência, como WhatsApp ou ligação:')?.trim();if(!evidence)return;if(evidence.length<4){setErr('Registre uma evidência do aceite para continuar.');return}if(!window.confirm(`Confirma que ${name} recebeu e leu escopo, valores e condições e aceitou expressamente o orçamento ORC-${String(q.quote_no).padStart(5,'0')} versão ${q.current_version}? Esta ação ficará registrada na auditoria.`))return;setBusy(true);setErr('');const{error}=await supabase.rpc('admin_record_quote_approval',{p_quote_id:q.id,p_customer_name:name,p_evidence:evidence});if(error)setErr(error.message);else{notify('Aceite do cliente registrado e orçamento aprovado.');await refresh()}setBusy(false)};const scheduleWorkOrder=async(order:Row)=>{if(!supabase)return;const raw=window.prompt('Data e hora local do serviço (ex.: 2026-10-20T14:00):');if(raw===null||!raw.trim())return;const scheduled=new Date(raw);if(Number.isNaN(scheduled.getTime())){setErr('Data e hora inválidas.');return}setBusy(true);const{error}=await supabase.from('work_orders').update({scheduled_at:scheduled.toISOString()}).eq('id',order.id).eq('status','scheduled');if(error)setErr(error.message);else notify('Serviço agendado.');await refresh();setBusy(false)};const changeWorkOrder=async(order:Row,status:'in_progress'|'completed'|'closed')=>{if(!supabase)return;let notes:string|null=null;let expenses=0;let authorized=false;if(status==='completed'){notes=window.prompt('Registre as atividades concluídas e observações de entrega:')||'';if(notes.trim().length<4){setErr('Adicione as observações de conclusão para continuar.');return}const raw=window.prompt('Despesas adicionais autorizadas pelo cliente (R$). Digite 0 se não houver:','0');if(raw===null)return;expenses=Number(raw.replace(',','.'));if(!Number.isFinite(expenses)||expenses<0){setErr('Valor de despesas inválido.');return}if(expenses>0){authorized=window.confirm(`Confirma que o cliente autorizou previamente o acréscimo de ${money(expenses)}?`);if(!authorized)return}}setBusy(true);const{error}=await supabase.rpc('set_work_order_status',{p_work_order_id:order.id,p_status:status,p_extra_expenses:expenses,p_completion_notes:notes,p_extra_expenses_authorized:authorized});if(error)setErr(error.message);else notify(status==='completed'?'Execução concluída e auditada.':status==='closed'?'Ordem encerrada.':'Ordem iniciada.');await refresh();setBusy(false)};const printWorkOrder=(order:Row)=>{const body=data.versions?.find(v=>v.quote_id===order.quote_id&&v.version===order.quote_version)||{};const safe=(x:any)=>String(x??'').replace(/[&<>"']/g,(m:string)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]!));const w=window.open('','_blank');if(!w)return;w.document.write(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Comprovante OS-${order.order_no}</title><style>body{font:14px Arial;color:#172033;max-width:800px;margin:36px auto;padding:0 24px;line-height:1.55}h1{color:#10264a}.brand{border-bottom:3px solid #c6a154;padding-bottom:14px}.box{background:#f4f6f9;padding:14px;border-radius:8px;margin:18px 0}</style><header class="brand"><h1>PH SERVICE FORTAL</h1><b>Comprovante da Ordem de Serviço OS-${safe(String(order.order_no).padStart(5,'0'))}</b></header><p><b>Cliente:</b> ${safe(order.clients?.name)}<br><b>Orçamento aprovado:</b> ORC-${safe(String(order.quotes?.quote_no||'').padStart(5,'0'))} · versão ${safe(order.quote_version)}<br><b>Agendamento:</b> ${order.scheduled_at?new Date(order.scheduled_at).toLocaleString('pt-BR'):'Não informado'}</p><div class="box"><b>Escopo:</b><br>${safe(body.description)}<br><br><b>Valor contratado:</b> ${money(body.total)}<br><b>Despesas autorizadas registradas:</b> ${money(order.extra_expenses)}</div><h2>Conclusão</h2><p>${safe(order.completion_notes||'Ainda não concluída.')}</p><p><b>Status:</b> ${safe(stateName(order.status))}</p><p>PH SERVICE FORTAL · (86) 99949-0316</p><script>window.print()</script></html>`);w.document.close()};const activeQuotes=data.quotes||[];const totalApproved=activeQuotes.filter(q=>q.status==='approved').reduce((a,q)=>a+Number(data.versions?.find(v=>v.quote_id===q.id&&v.version===q.current_version)?.total||0),0);const totals=(data.payments||[]).filter(p=>p.status==='received').reduce((a,p)=>a+Number(p.amount),0);
const openEdit=(kind:string,row:Row)=>{setEditing(row);setSelected(null);if(kind==='quote'){const v=data.versions?.find(x=>x.quote_id===row.id&&x.version===row.current_version);setQuoteItems((v?.items||[{description:'',quantity:'1',unit_price:''}]).map((x:Row)=>({...x,quantity:String(x.quantity),unit_price:String(x.unit_price)})));setCardFeeRate(String(v?.card_fee_rate||0));setModal('quote')}else setModal(kind+'-edit')};const createOrder=async(q:Row)=>{if(!supabase)return;let when=window.prompt('Data e hora do serviço (ex.: 2026-10-20T14:00). Deixe vazio para agendar depois:')||'';const scheduledAt=when?new Date(when).toISOString():null;if(when&&Number.isNaN(new Date(when).getTime())){setErr('Data e hora inválidas.');return}setBusy(true);const{data:id,error}=await supabase.rpc('create_work_order_from_approved_quote',{p_quote_id:q.id,p_scheduled_at:scheduledAt});if(error)setErr(error.message);else notify(`Ordem de serviço criada: ${id}`);await refresh();setBusy(false)};const quotePreview=()=>{const subtotal=quoteItems.reduce((sum,item)=>sum+(Number(item.quantity)||0)*(Number(item.unit_price)||0),0);const value=(name:string)=>Number((document.querySelector(`[name=\"${name}\"]`) as HTMLInputElement|null)?.value||0);const base=Math.max(0,subtotal+value('additions')+value('expenses')-value('discount'));const method=(document.querySelector('[name=\"payment_method\"]') as HTMLSelectElement|null)?.value||'pix';const fee=['debit','credit','installment'].includes(method)?Math.round(base*Number(cardFeeRate||0))/100:0;return {subtotal,fee,total:Math.max(0,base+fee)}};async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase){setErr('Conecte o projeto Supabase para salvar dados.');return}setBusy(true);setErr('');const f=new FormData(e.currentTarget);let result:any;const companyId=company?.id;if(!companyId){setErr('A empresa ainda não foi inicializada. Siga o provisionamento no README.');setBusy(false);return}try{if(modal==='client'||modal==='client-edit'){const payload={company_id:companyId,name:f.get('name'),client_type:f.get('client_type'),document:f.get('document')||null,phone:normalizeBrazilPhone(f.get('phone')),email:f.get('email')||null,address:{street:f.get('street')||'',number:f.get('number')||'',neighborhood:f.get('neighborhood')||'',city:f.get('city')||'Fortaleza',state:f.get('state')||'CE',zip:f.get('zip')||''},notes:f.get('notes')||''};result=modal==='client-edit'?await supabase.from('clients').update(payload).eq('id',editing?.id):await supabase.from('clients').insert(payload)}else if(modal==='service'||modal==='service-edit'){const payload={company_id:companyId,category_id:f.get('category_id')||null,name:f.get('name'),code:f.get('code')||null,unit:f.get('unit'),description:f.get('description')||'',standard_price:f.get('standard_price')?Number(f.get('standard_price')):null,estimated_cost:f.get('estimated_cost')?Number(f.get('estimated_cost')):null,estimated_duration:f.get('estimated_duration')||null,materials:f.get('materials')||null,warranty:f.get('warranty')||null};result=modal==='service-edit'?await supabase.from('services').update(payload).eq('id',editing?.id):await supabase.from('services').insert(payload)}else if(modal==='quote'){const items=quoteItems.map(item=>({description:String(item.description||'').trim(),quantity:Number(item.quantity),unit_price:Number(item.unit_price)}));if(!items.length||items.some(item=>!item.description||!Number.isFinite(item.quantity)||item.quantity<=0||!Number.isFinite(item.unit_price)||item.unit_price<0)){setErr('Confira a descrição, a quantidade e o valor de cada item.');setBusy(false);return}const{data:id,error}=await supabase.rpc('save_quote_version',{p_company_id:companyId,p_quote_id:editing?.id||null,p_client_id:editing?.client_id||f.get('client_id'),p_valid_until:f.get('valid_until')||null,p_description:f.get('description')||'',p_service_address:editing?(data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.service_address||{}):{},p_items:items,p_additions:Number(f.get('additions')||0),p_expenses:Number(f.get('expenses')||0),p_discount:Number(f.get('discount')||0),p_duration:f.get('duration')||null,p_payment_terms:f.get('payment_terms')||null,p_warranty:f.get('warranty')||null,p_notes:f.get('notes')||null,p_payment_method:f.get('payment_method'),p_entry_amount:Number(f.get('entry_amount')||0),p_installments_count:Number(f.get('installments_count')||1),p_card_fee_rate:Number(f.get('card_fee_rate')||0)});result={error};if(!error){notify(`${editing?'Nova versão do orçamento salva':'Orçamento salvo'}: ${id}. Total calculado no banco de dados.`);setModal('');await refresh();setBusy(false);return}}else if(modal==='payment'||modal==='payment-edit'){const payload={company_id:companyId,client_id:f.get('client_id'),quote_id:f.get('quote_id')||null,amount:Number(f.get('amount')),method:f.get('method'),status:f.get('status'),paid_at:f.get('status')==='received'?(editing?.paid_at||new Date().toISOString()):null,due_at:f.get('due_at')||null,notes:f.get('notes')||''};result=modal==='payment-edit'?await supabase.from('payments').update(payload).eq('id',editing?.id):await supabase.from('payments').insert(payload)}if(result?.error)throw result.error;setModal('');notify('Registro salvo com sucesso.');await refresh()}catch(e:any){setErr(e.message||'Não foi possível salvar.')}finally{setBusy(false)}}
const filtered=(rows:Row[])=>rows.filter(r=>JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));const table=(rows:Row[],cols:{key:string;label:string;render?:(r:Row)=>any}[],empty:string,kind='')=><div className="table-wrap"><table><thead><tr>{cols.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{filtered(rows).map((r,i)=><tr key={r.id||i} onClick={()=>setSelected({...r,__kind:kind})}>{cols.map(c=><td key={c.key}>{c.render?c.render(r):r[c.key]||'—'}</td>)}</tr>)}</tbody></table>{!filtered(rows).length&&<div className="empty"><span>{empty}</span></div>}</div>;
if(!ready)return <div className="loading"><LoaderCircle className="spin"/>Carregando…</div>;if(!configured)return <div className="setup"><div className="login-brand"><img className="brand-logo" src="/logo-ph-service-fortal.webp" alt="PH SERVICE FORTAL"/><div><strong>PH O.S.</strong><small>GESTÃO DE SERVIÇOS</small></div></div><div className="setup-card"><ShieldCheck size={32}/><h1>Seu espaço de gestão está pronto para conectar</h1><p>O espaço da PH SERVICE FORTAL está configurado no projeto Supabase dedicado <code>hyixoosgozqyehegfzlh</code>.</p><ol><li>Configure <code>VITE_SUPABASE_URL</code> com o endereço do projeto PH O.S.</li><li>Use somente a chave publicável do projeto no frontend.</li><li>Não use nem compartilhe a chave administrativa <code>service_role</code>.</li></ol><div className="setup-note">Nenhum dado comercial fictício foi inserido. Valores e dados cadastrais ficam vazios até você configurá-los.</div></div></div>;
if(recovery)return <div className="setup"><div className="login-brand"><img className="brand-logo" src="/logo-ph-service-fortal.webp" alt="PH SERVICE FORTAL"/><div><strong>PH O.S.</strong><small>GESTÃO DE SERVIÇOS</small></div></div><form className="login-card" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const password=String(f.get('password')||'');if(password!==String(f.get('confirm_password')||'')){setErr('As senhas não coincidem.');return}setBusy(true);setErr('');const{error}=await supabase!.auth.updateUser({password});setBusy(false);if(error)setErr('Não foi possível atualizar a senha. Solicite um novo link e tente novamente.');else{setRecovery(false);setOk('')}}}><h1>Defina uma nova senha</h1><p>Escolha uma senha com pelo menos 8 caracteres.</p><label>Nova senha<input type="password" name="password" minLength={8} required autoComplete="new-password"/></label><label>Confirme a senha<input type="password" name="confirm_password" minLength={8} required autoComplete="new-password"/></label>{err&&<div className="error">{err}</div>}<button className="primary wide" disabled={busy}>{busy?'Salvando…':'Salvar nova senha'}</button></form></div>;
if(!session)return <div className="setup"><div className="login-brand"><img className="brand-logo" src="/logo-ph-service-fortal.webp" alt="PH SERVICE FORTAL"/><div><strong>PH O.S.</strong><small>GESTÃO DE SERVIÇOS</small></div></div><form className="login-card" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const{error}=await supabase!.auth.signInWithPassword({email:String(f.get('email')),password:String(f.get('password'))});if(error)setErr(error.message)}}><h1>Acesse sua conta</h1><p>Entre para gerenciar os atendimentos da empresa.</p><label>E-mail<input type="email" name="email" required/></label><label>Senha<input type="password" name="password" required/></label>{err&&<div className="error">{err}</div>}<button className="primary wide">Entrar</button><button type="button" className="secondary wide" onClick={async e=>{const email=String(new FormData(e.currentTarget.form!).get('email')||'').trim();if(!email){setErr('Informe seu e-mail para receber o link de recuperação.');return}setBusy(true);setErr('');const{error}=await supabase!.auth.resetPasswordForEmail(email);setBusy(false);if(error)setErr('Não foi possível solicitar a recuperação agora. Tente novamente mais tarde.');else setOk('Se este e-mail estiver cadastrado, enviaremos instruções para redefinir a senha.')}} disabled={busy}>Esqueci minha senha</button>{ok&&<div className="form-hint">{ok}</div>}<small>Cadastro de usuários deve ser feito pelo administrador no Supabase Auth.</small></form></div>;
const downloadReportCsv=()=>{const pending=(data.payments||[]).filter(p=>p.status==='pending').reduce((a,p)=>a+Number(p.amount||0),0);const approved=(data.quotes||[]).filter(q=>q.status==='approved').length;const rows=[['Indicador','Valor'],['Clientes cadastrados',String(data.clients?.length||0)],['Orçamentos emitidos',String(data.quotes?.length||0)],['Orçamentos aprovados',String(approved)],['Taxa de aprovação',data.quotes?.length?`${Math.round(approved/data.quotes.length*100)}%`:'0%'],['Valor aprovado',money(totalApproved)],['Valor recebido',money(totals)],['Valor pendente',money(pending)],['Gerado em',new Date().toLocaleString('pt-BR')]];const cell=(v:unknown)=>`"${String(v??'').replaceAll('\"','\"\"')}"`;const csv='\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`ph-os-relatorio-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};const addAction=()=>setModal(({Clientes:'client',Orçamentos:'quote',Financeiro:'payment'} as any)[section]||'');const actionLabel=({Clientes:'Novo cliente',Orçamentos:'Novo orçamento',Financeiro:'Registrar pagamento'}as any)[section];
return <div className="app"><aside className={`sidebar ${mobile?'show':''}`}><div className="side-brand"><img className="brand-logo" src="/logo-ph-service-fortal.webp" alt="PH SERVICE FORTAL"/><div><b>PH O.S.</b><small>GESTÃO DE SERVIÇOS</small></div><button className="icon mobile-close" onClick={()=>setMobile(false)}><X/></button></div><div className="company-chip"><span className="pulse"/> Ambiente privado <ChevronDown size={14}/></div><nav>{nav.map(n=><button key={n.name} className={section===n.name?'nav active':'nav'} onClick={()=>{setSection(n.name);setMobile(false);setQuery('')}}><n.icon size={18}/>{n.name}</button>)}</nav><div className="side-footer"><div className="avatar">{session.user.email?.[0]?.toUpperCase()}</div><div className="user-info"><b>{session.user.email}</b><small>Administrador</small></div><button className="icon" title="Sair" onClick={()=>supabase!.auth.signOut()}><LogOut size={17}/></button></div></aside><main><header className="topbar"><button className="icon hamburger" onClick={()=>setMobile(true)}><Menu/></button><div className="topbar-brand"><img className="topbar-logo" src="/logo-ph-service-fortal.webp" alt="Logo PH SERVICE FORTAL"/><div><span className="eyebrow">PH SERVICE FORTAL</span><h1>{section}</h1></div></div><div className="top-actions"><span className="secure"><ShieldCheck size={15}/> Conexão segura</span><button className="avatar mini">{session.user.email?.[0]?.toUpperCase()}</button></div></header><div className="content">{err&&<div className="toast error"><span>{err}</span><button onClick={()=>setErr('')}><X size={16}/></button></div>}{ok&&<div className="toast success"><Check size={16}/>{ok}</div>}
{section==='Dashboard'&&<><div className="welcome"><div><h2>Bom dia, equipe 👋</h2><p>Acompanhe sua operação em um só lugar.</p></div><button className="primary" onClick={()=>{setEditing(null);setCardFeeRate('0');setModal('quote')}}><Plus size={17}/> Novo orçamento</button></div><div className="stat-grid">{[{label:'Orçamentos em análise',value:(data.quotes||[]).filter(q=>['draft','sent','change_requested'].includes(q.status)).length,icon:FileText,color:'blue'},{label:'Orçamentos aprovados',value:(data.quotes||[]).filter(q=>q.status==='approved').length,icon:FileCheck2,color:'gold'},{label:'Serviços agendados',value:(data.orders||[]).filter(o=>o.status==='scheduled').length,icon:CalendarDays,color:'violet'},{label:'Recebido',value:money(totals),icon:Wallet,color:'green'}].map(s=><div className="stat" key={s.label}><div className={`stat-icon ${s.color}`}><s.icon size={19}/></div><div><small>{s.label}</small><strong>{s.value}</strong></div><span className="stat-arrow"><ArrowUpRight size={15}/></span></div>)}</div><div className="dashboard-grid"><section className="panel wide-panel"><div className="panel-head"><div><h3>Orçamentos recentes</h3><p>Propostas e aprovações dos clientes</p></div><button className="link" onClick={()=>setSection('Orçamentos')}>Ver todos →</button></div>{table((data.quotes||[]).slice(0,6),[{key:'quote_no',label:'Orçamento',render:r=><b className="ref">ORC-{String(r.quote_no).padStart(5,'0')}</b>},{key:'clients',label:'Cliente',render:r=>r.clients?.name||'—'},{key:'created_at',label:'Emissão',render:r=>dt(r.created_at)},{key:'status',label:'Status',render:r=><span className={`badge ${slug(r.status)}`}>{stateName(r.status)}</span>}],'Nenhum orçamento cadastrado ainda.')}</section><section className="panel"><div className="panel-head"><div><h3>Próximos serviços</h3><p>Agenda operacional</p></div><CalendarDays size={18}/></div>{(data.orders||[]).filter(o=>o.scheduled_at).slice(0,5).map(o=><div className="event" key={o.id}><div className="event-date"><b>{new Date(o.scheduled_at).getDate()}</b><small>{new Date(o.scheduled_at).toLocaleDateString('pt-BR',{month:'short'})}</small></div><div><b>{o.clients?.name||'Cliente'}</b><small>{new Date(o.scheduled_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} · OS #{o.order_no}</small></div><span className={`dot ${o.status}`}/></div>)}{!(data.orders||[]).some(o=>o.scheduled_at)&&<div className="empty compact">Nenhum serviço agendado.</div>}</section></div><div className="dashboard-grid bottom-grid"><section className="panel"><div className="panel-head"><div><h3>Visão comercial</h3><p>Com base nos dados cadastrados</p></div><BriefcaseBusiness size={18}/></div><div className="finance-line"><span><ArrowUpRight size={15}/> Valor aprovado</span><b>{money(totalApproved)}</b></div><div className="finance-line"><span><ArrowDownLeft size={15}/> Valores recebidos</span><b>{money(totals)}</b></div><div className="finance-line"><span><Clock3 size={15}/> Em aberto</span><b>{money((data.payments||[]).filter(p=>p.status==='pending').reduce((a,p)=>a+Number(p.amount),0))}</b></div></section><section className="panel contact-panel"><div className="contact-symbol">PH<span>.</span></div><div><b>PH SERVICE FORTAL</b><p>Fortaleza — CE · Serviços técnicos, instalações e soluções digitais.</p><a href="https://wa.me/558699490316" target="_blank" rel="noreferrer"><MessageCircle size={14}/> Atendimento comercial</a></div></section></div></>}
{section==='Clientes'&&<section className="panel"><div className="panel-head"><div><h3>Clientes</h3><p>Cadastro e histórico dos atendimentos</p></div><button className="primary" onClick={()=>{setEditing(null);setModal('client')}}><Plus size={16}/> Novo cliente</button></div><div className="toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Buscar por nome, telefone ou documento" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="muted">{data.clients?.length||0} clientes</span></div>{table(data.clients||[],[{key:'name',label:'Cliente',render:r=><div className="person-cell"><span className="person-avatar">{r.name?.[0]}</span><div><b>{r.name}</b><small>{r.client_type==='business'?'Pessoa jurídica':'Pessoa física'}</small></div></div>},{key:'phone',label:'Telefone'},{key:'email',label:'E-mail'},{key:'document',label:'CPF / CNPJ'},{key:'created_at',label:'Cadastro',render:r=>dt(r.created_at)},{key:'actions',label:'Ações',render:r=><button className="mini-action" onClick={e=>{e.stopPropagation();openEdit('client',r)}}>Editar</button>}],'Cadastre o primeiro cliente para começar.','client')}</section>}
{section==='Catálogo'&&<section className="panel"><div className="panel-head"><div><h3>Catálogo de serviços</h3><p>Valores podem ser definidos por orçamento. Nenhum preço padrão foi presumido.</p></div><button className="primary" onClick={()=>{setEditing(null);setModal('service')}}><Plus size={16}/> Novo serviço</button></div>{table(data.services||[],[{key:'name',label:'Serviço',render:r=><b>{r.name}</b>},{key:'code',label:'Código'},{key:'unit',label:'Unidade',render:r=>({service:'Serviço',hour:'Hora',day:'Diária',meter:'Metro',unit:'Unidade',quantity:'Quantidade'}as any)[r.unit]||r.unit},{key:'standard_price',label:'Preço padrão',render:r=>r.standard_price==null?'A definir':money(r.standard_price)},{key:'active',label:'Status',render:r=><span className={`badge ${r.active?'approved':'cancelled'}`}>{r.active?'Ativo':'Inativo'}</span>},{key:'actions',label:'Ações',render:r=><button className="mini-action" onClick={e=>{e.stopPropagation();openEdit('service',r)}}>Editar</button>}],'Cadastre os serviços oferecidos pela empresa.','service')}</section>}

{section==='Orçamentos'&&<section className="panel"><div className="panel-head"><div><h3>Orçamentos</h3><p>Propostas com versões, aprovação segura, condições e taxas discriminadas.</p></div><button className="primary" onClick={()=>{setEditing(null);setCardFeeRate('0');setQuoteItems([{description:'',quantity:'1',unit_price:''}]);setModal('quote')}}><Plus size={16}/> Novo orçamento</button></div><div className="toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Buscar número ou cliente" value={query} onChange={e=>setQuery(e.target.value)}/></div><label className="status-filter">Situação do orçamento<select value={quoteStatusFilter} onChange={e=>setQuoteStatusFilter(e.target.value)}><option value="all">Todas</option><option value="draft">Rascunho</option><option value="sent">Enviado</option><option value="approved">Aprovado</option><option value="declined">Recusado</option><option value="change_requested">Alteração solicitada</option><option value="expired">Expirado</option></select></label></div>{table((data.quotes||[]).filter(q=>quoteStatusFilter==='all'||q.status===quoteStatusFilter),[{key:'quote_no',label:'Orçamento',render:r=><b className="ref">ORC-{String(r.quote_no).padStart(5,'0')}</b>},{key:'clients',label:'Cliente',render:r=>r.clients?.name||'—'},{key:'created_at',label:'Emissão',render:r=>dt(r.created_at)},{key:'valid_until',label:'Validade',render:r=>dt(r.valid_until)},{key:'current_version',label:'Versão',render:r=>`v${r.current_version}`},{key:'total',label:'Total',render:r=>money(data.versions?.find(v=>v.quote_id===r.id&&v.version===r.current_version)?.total)},{key:'status',label:'Status',render:r=><span className={`badge ${slug(r.status)}`}>{r.status==='approved'?'✓ APROVADO':r.status==='declined'?'RECUSADO':r.status==='sent'?'AGUARDANDO APROVAÇÃO':stateName(r.status)}</span>},{key:'share',label:'Atalhos',render:r=><div className="row-actions">{['draft','sent','change_requested'].includes(r.status)&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();approveQuoteManually(r)}}><Check size={15}/> Aprovar orçamento</button>}<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();downloadQuotePdf(r)}}><Download size={15}/> Baixar PDF</button><button className="mini-action" disabled={busy||!['draft','change_requested','sent'].includes(r.status)} onClick={e=>{e.stopPropagation();shareQuote(r)}}><MessageCircle size={15}/> Enviar PDF + WhatsApp</button><button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();openEdit('quote',r)}}>Editar / nova versão</button>{r.status==='approved'&&!data.orders?.some(o=>o.quote_id===r.id&&o.quote_version===r.current_version)&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();createOrder(r)}}><HardHat size={15}/> Criar OS</button>}</div>}],'Nenhum orçamento criado. Os itens e totais ficam congelados em versões.','quote')}</section>}

{section==='Ordens de serviço'&&<section className="panel"><div className="panel-head"><div><h3>Ordens de serviço</h3><p>Agenda, execução, despesas autorizadas e comprovante.</p></div><span className="muted"><HardHat size={15}/> Criadas após a aprovação do orçamento pelo cliente</span></div>{table(data.orders||[],[{key:'order_no',label:'Ordem',render:r=><b className="ref">OS-{String(r.order_no).padStart(5,'0')}</b>},{key:'clients',label:'Cliente',render:r=>r.clients?.name||'—'},{key:'quotes',label:'Orçamento',render:r=>r.quotes?.quote_no?`ORC-${String(r.quotes.quote_no).padStart(5,'0')}`:'—'},{key:'scheduled_at',label:'Agendamento',render:r=>r.scheduled_at?new Date(r.scheduled_at).toLocaleString('pt-BR'):r.status==='scheduled'?'A agendar':'—'},{key:'status',label:'Status',render:r=><span className={`badge ${slug(r.status)}`}>{stateName(r.status)}</span>},{key:'actions',label:'Ações',render:r=><div className="row-actions"><button className="mini-action" onClick={e=>{e.stopPropagation();printWorkOrder(r)}}><Download size={15}/> Comprovante</button>{r.status==='scheduled'&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();scheduleWorkOrder(r)}}>Agendar</button>}{r.status==='scheduled'&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();changeWorkOrder(r,'in_progress')}}>Iniciar</button>}{r.status==='in_progress'&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();changeWorkOrder(r,'completed')}}>Concluir</button>}{r.status==='completed'&&<button className="mini-action" disabled={busy} onClick={e=>{e.stopPropagation();changeWorkOrder(r,'closed')}}>Encerrar</button>}</div>}],'As ordens são criadas automaticamente quando o orçamento aprovado tem aceite registrado.','work_order')}</section>}
{section==='Financeiro'&&<section className="panel"><div className="panel-head"><div><h3>Pagamentos</h3><p>Registre recebimentos e valores pendentes.</p></div><button className="primary" onClick={()=>{setEditing(null);setModal('payment')}}><Plus size={16}/> Registrar pagamento</button></div><div className="stat-grid finance-stats"><div className="stat"><div className="stat-icon green"><ArrowDownLeft/></div><div><small>Recebido</small><strong>{money(totals)}</strong></div></div><div className="stat"><div className="stat-icon gold"><Clock3/></div><div><small>Pendente</small><strong>{money((data.payments||[]).filter(p=>p.status==='pending').reduce((a,p)=>a+Number(p.amount),0))}</strong></div></div></div>{table(data.payments||[],[{key:'clients',label:'Cliente',render:r=>r.clients?.name||'—'},{key:'amount',label:'Valor',render:r=>money(r.amount)},{key:'method',label:'Forma',render:r=>({pix:'Pix',cash:'Dinheiro',debit:'Débito',credit:'Crédito',transfer:'Transferência',installment:'Parcelado',other:'Outro'}as any)[r.method]},{key:'status',label:'Situação',render:r=><span className={`badge ${r.status==='received'?'approved':'awaiting_payment'}`}>{r.status==='received'?'Recebido':'Pendente'}</span>},{key:'paid_at',label:'Recebido em',render:r=>dt(r.paid_at||r.due_at)},{key:'actions',label:'Ações',render:r=><div className="row-actions"><button className="mini-action" disabled={r.status!=='received'} onClick={e=>{e.stopPropagation();downloadReceipt(r)}}><Download size={15}/> Baixar recibo PDF</button><button className="mini-action" disabled={r.status!=='received'} onClick={e=>{e.stopPropagation();sendReceiptToWhatsApp(r)}}><MessageCircle size={15}/> WhatsApp do cliente</button><button className="mini-action" onClick={e=>{e.stopPropagation();openEdit('payment',r)}}>Editar</button></div>}],'Nenhum pagamento registrado.','payment')}</section>}
{section==='Relatórios'&&<section className="panel"><div className="panel-head"><div><h3>Resumo operacional</h3><p>Indicadores calculados a partir dos registros reais.</p></div><div className="button-row"><button className="secondary" onClick={()=>window.print()}><Download size={15}/> Imprimir resumo</button><button className="secondary" onClick={downloadReportCsv}><Download size={15}/> Baixar CSV</button></div></div><div className="report-grid">{[{label:'Clientes cadastrados',n:data.clients?.length||0},{label:'Orçamentos emitidos',n:data.quotes?.length||0},{label:'Taxa de aprovação',n:(data.quotes?.length?Math.round(data.quotes.filter(q=>q.status==='approved').length/data.quotes.length*100):0)+'%'},{label:'Valor aprovado',n:money(totalApproved)},{label:'Valor recebido',n:money(totals)}].map(r=><div className="report-card" key={r.label}><small>{r.label}</small><strong>{r.n}</strong></div>)}</div></section>}
{section==='Configurações'&&<section className="panel"><div className="panel-head"><div><h3>Dados comerciais</h3><p>Informações utilizadas em propostas e documentos.</p></div><Settings size={18}/></div><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(!company){setErr('A empresa ainda não foi inicializada.');return}const{error}=await supabase!.from('companies').update({name:f.get('name'),phone:f.get('phone'),legal_id:f.get('legal_id'),whatsapp_url:f.get('whatsapp_url'),website:f.get('website')}).eq('id',company.id);if(error)setErr(error.message);else{notify('Dados atualizados.');await refresh()}}} className="settings-form"><label>Nome comercial<input name="name" defaultValue={company?.name||'PH SERVICE FORTAL'}/></label><label>Telefone comercial<input name="phone" defaultValue={company?.phone||''} placeholder="Preencher"/></label><label>CNPJ ou CPF<input name="legal_id" defaultValue={company?.legal_id||''} placeholder="Preencher"/></label><label>Link WhatsApp<input name="whatsapp_url" defaultValue={company?.whatsapp_url||'https://wa.me/558699490316'}/></label><label>Site<input name="website" defaultValue={company?.website||'https://ph-service-fortal.vercel.app/'}/></label><button className="primary">Salvar configurações</button></form><p className="muted privacy"><ShieldCheck size={15}/> Arquivos e anexos devem ficar em bucket privado com políticas de armazenamento antes do uso com documentos reais.</p></section>}
</div></main>{selected&&<div className="drawer-backdrop" onClick={()=>setSelected(null)}><div className="drawer" onClick={e=>e.stopPropagation()}><button className="icon drawer-close" onClick={()=>setSelected(null)}><X/></button><span className="eyebrow">DETALHES</span><h2>{selected.__kind==='work_order'?`Ordem OS-${String(selected.order_no).padStart(5,'0')}`:selected.name||selected.summary||`Registro #${selected.ticket_no||selected.quote_no||selected.order_no||''}`}</h2><section className="panel detail-list">{selected.__kind==='client'&&<><p><b>Tipo:</b> {selected.client_type==='business'?'Pessoa jurídica':'Pessoa física'}</p><p><b>Documento:</b> {selected.document||'—'}</p><p><b>Telefone:</b> {selected.phone||'—'}</p><p><b>E-mail:</b> {selected.email||'—'}</p><p><b>Endereço:</b> {[selected.address?.street,selected.address?.number,selected.address?.neighborhood,selected.address?.city,selected.address?.state,selected.address?.zip].filter(Boolean).join(', ')||'—'}</p><p><b>Observações:</b> {selected.notes||'—'}</p><button className="primary" onClick={()=>openEdit('client',selected)}>Editar cadastro</button></>}{selected.__kind==='service'&&<><p><b>Código:</b> {selected.code||'—'}</p><p><b>Unidade:</b> {selected.unit}</p><p><b>Preço padrão:</b> {selected.standard_price==null?'A definir':money(selected.standard_price)}</p><p><b>Descrição:</b> {selected.description||'—'}</p><button className="primary" onClick={()=>openEdit('service',selected)}>Editar serviço</button></>}{selected.__kind==='payment'&&<><p><b>Cliente:</b> {selected.clients?.name||'—'}</p><p><b>Valor:</b> {money(selected.amount)}</p><p><b>Forma:</b> {selected.method}</p><p><b>Situação:</b> {selected.status==='received'?'Recebido':'Pendente'}</p><p><b>Observação:</b> {selected.notes||'—'}</p><button className="primary" onClick={()=>openEdit('payment',selected)}>Editar lançamento</button></>}{selected.__kind==='quote'&&<><p><b>Cliente:</b> {selected.clients?.name||'—'}</p><p><b>Orçamento:</b> ORC-{String(selected.quote_no).padStart(5,'0')} · versão {selected.current_version}</p><p><b>Status:</b> {stateName(selected.status)}</p><p><b>Validade:</b> {dt(selected.valid_until)}</p><button className="primary" onClick={()=>openEdit('quote',selected)}>Editar / criar nova versão</button></>}{selected.__kind==='work_order'&&<><p><b>Cliente:</b> {selected.clients?.name||'—'}</p><p><b>Orçamento:</b> ORC-{String(selected.quotes?.quote_no||'').padStart(5,'0')} · versão {selected.quote_version}</p><p><b>Agendamento:</b> {selected.scheduled_at?new Date(selected.scheduled_at).toLocaleString('pt-BR'):'A definir'}</p><p><b>Status:</b> {stateName(selected.status)}</p><p><b>Serviços:</b> {(data.versions?.find(v=>v.quote_id===selected.quote_id&&v.version===selected.quote_version)?.items||[]).map((i:Row)=>i.description).join(', ')||'—'}</p><p><b>Valor aprovado:</b> {money(data.versions?.find(v=>v.quote_id===selected.quote_id&&v.version===selected.quote_version)?.total)}</p><p><b>Observações de conclusão:</b> {selected.completion_notes||'—'}</p><button className="secondary" onClick={()=>printWorkOrder(selected)}><Download size={15}/> Comprovante</button>{selected.status==='scheduled'&&!selected.scheduled_at&&<button className="secondary" onClick={()=>scheduleWorkOrder(selected)}>Agendar serviço</button>}{selected.status==='scheduled'&&<button className="primary" onClick={()=>changeWorkOrder(selected,'in_progress')}>Iniciar serviço</button>}{selected.status==='in_progress'&&<button className="primary" onClick={()=>changeWorkOrder(selected,'completed')}>Concluir serviço</button>}{selected.status==='completed'&&<button className="primary" onClick={()=>changeWorkOrder(selected,'closed')}>Encerrar ordem</button>}</>}</section><button className="secondary" onClick={()=>setSelected(null)}>Fechar</button></div></div>}
{modal&&<div className="modal-backdrop" onClick={()=>setModal('')}><form className="modal" onSubmit={submit} onChange={e=>{const t=e.target as HTMLInputElement;if(t.name==='card_fee_rate')setCardFeeRate(t.value);else setQuotePreviewTick(x=>x+1)}} onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">PH SERVICE FORTAL</span><h2>{{client:editing?'Editar cliente':'Novo cliente', 'client-edit':'Editar cliente',quote:editing?'Editar orçamento / nova versão':'Criar orçamento',payment:'Registrar pagamento','payment-edit':'Editar pagamento',service:'Novo serviço','service-edit':'Editar serviço'}[modal]||'Novo registro'}</h2></div><button type="button" className="icon" onClick={()=>{setModal('');setEditing(null)}}><X/></button></div>
{(modal==='client'||modal==='client-edit')&&<><div className="form-grid"><label className="span2">Nome completo / Razão social<input name="name" required autoFocus defaultValue={editing?.name||''}/></label><label>Tipo de cliente<select name="client_type" defaultValue={editing?.client_type||'person'}><option value="person">Pessoa física</option><option value="business">Pessoa jurídica</option></select></label><label>CPF / CNPJ<input name="document" defaultValue={editing?.document||''}/></label><label>Telefone / WhatsApp<input name="phone" type="tel" inputMode="tel" placeholder="(85) 99999-9999" defaultValue={editing?.phone?.replace(/^\+55/,'')||editing?.phone||''}/><small className="form-hint">Código do Brasil +55 incluído automaticamente.</small></label><label>E-mail<input type="email" name="email" defaultValue={editing?.email||''}/></label><label>Rua<input name="street" defaultValue={editing?.address?.street||''}/></label><label>Número / complemento<input name="number" defaultValue={editing?.address?.number||''}/></label><label>Bairro<input name="neighborhood" defaultValue={editing?.address?.neighborhood||''}/></label><label>Cidade<input name="city" defaultValue={editing?.address?.city||'Fortaleza'}/></label><label>Estado<input name="state" defaultValue={editing?.address?.state||'CE'} maxLength={2}/></label><label>CEP<input name="zip" defaultValue={editing?.address?.zip||''}/></label><label className="span2">Observações internas<textarea name="notes" rows={2} defaultValue={editing?.notes||''}/></label></div></>}
{modal==='quote'&&<div className="form-grid" data-preview={quotePreviewTick}><label className="span2">Cliente<select required name="client_id" disabled={!!editing} defaultValue={editing?.client_id||''}><option value="">Selecione</option>{data.clients?.map(c=><option value={c.id}>{c.name}</option>)}</select></label><label className="span2">Descrição geral<input name="description" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.description||'':''}/></label><div className="span2 quote-items-heading"><strong>Itens do orçamento</strong><button type="button" className="secondary add-quote-item" onClick={()=>setQuoteItems(items=>[...items,{description:'',quantity:'1',unit_price:''}])}><Plus size={15}/> Adicionar item</button></div>{quoteItems.map((item,index)=><div className="quote-item-row span2" key={index}><label className="quote-description">Descrição<input required value={item.description} onChange={e=>setQuoteItems(items=>items.map((row,i)=>i===index?{...row,description:e.target.value}:row))} placeholder="Serviço ou material"/></label><label>Quantidade<input type="number" step="0.01" min="0.01" required value={item.quantity} onChange={e=>setQuoteItems(items=>items.map((row,i)=>i===index?{...row,quantity:e.target.value}:row))}/></label><label>Valor unitário<input type="number" step="0.01" min="0" required value={item.unit_price} onChange={e=>setQuoteItems(items=>items.map((row,i)=>i===index?{...row,unit_price:e.target.value}:row))}/></label><button type="button" className="icon remove-quote-item" title="Remover item" aria-label={`Remover item ${index+1}`} disabled={quoteItems.length===1} onClick={()=>setQuoteItems(items=>items.filter((_,i)=>i!==index))}><X size={16}/></button></div>)}<div className="span2 quote-subtotal-preview"><span>Subtotal dos itens</span><b>{money(quoteItems.reduce((sum,item)=>sum+(Number(item.quantity)||0)*(Number(item.unit_price)||0),0))}</b></div><label>Validade<input type="date" name="valid_until" defaultValue={editing?.valid_until||''}/></label><label>Prazo estimado<input name="duration" placeholder="A definir" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.estimated_duration||'':''}/></label><label>Acréscimos (R$)<input type="number" name="additions" step="0.01" min="0" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.additions||0:0}/></label><label>Despesas / deslocamento (R$)<input type="number" name="expenses" step="0.01" min="0" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.expenses||0:0}/></label><label>Desconto (R$)<input type="number" name="discount" step="0.01" min="0" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.discount||0:0}/></label><label>Garantia<input name="warranty" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.warranty||'':''}/></label><label>Forma de pagamento<select name="payment_method" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.payment_method||'pix':'pix'}><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="debit">Cartão de débito</option><option value="credit">Cartão de crédito</option><option value="transfer">Transferência</option><option value="installment">Parcelado no cartão</option><option value="entry_balance">Entrada + saldo na conclusão</option></select></label><label>Entrada (R$)<input type="number" min="0" step="0.01" name="entry_amount" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.entry_amount||0:0}/></label><label>Parcelas<input type="number" min="1" step="1" name="installments_count" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.installments_count||1:1}/></label><label>Taxa adicional da operadora (%)<input type="number" min="0" max="100" step="0.01" name="card_fee_rate" value={cardFeeRate} onChange={e=>setCardFeeRate(e.target.value)}/></label><label className="span2">Condições complementares<textarea name="payment_terms" rows={2} defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.payment_terms||'':''}/></label><p className="form-hint span2">Taxa adicional da operadora: {money(quotePreview().fee)} · Total previsto: {money(quotePreview().total)}. Percentual informado pelo administrador; nenhum valor de operadora é presumido.</p><label className="span2">Observações<textarea name="notes" rows={2} defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.notes||'':''}/></label><p className="form-hint span2">Você pode incluir vários serviços e materiais. O total oficial é calculado no PostgreSQL com arredondamento por item e proteção contra desconto acima do total.</p></div>}
{(modal==='payment'||modal==='payment-edit')&&<div className="form-grid"><label className="span2">Cliente<select required name="client_id" defaultValue={editing?.client_id||''}><option value="">Selecione</option>{data.clients?.map(c=><option value={c.id}>{c.name}</option>)}</select></label><label className="span2">Orçamento relacionado<select name="quote_id" defaultValue={editing?.quote_id||''}><option value="">Sem vínculo</option>{data.quotes?.map(q=><option value={q.id}>ORC-{String(q.quote_no).padStart(5,'0')} · {q.clients?.name||'Cliente'}</option>)}</select></label><label>Valor recebido / devido<input type="number" name="amount" step="0.01" min="0.01" required defaultValue={editing?.amount||''}/></label><label>Forma<select name="method" defaultValue={editing?.method||'pix'}><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="debit">Cartão de débito</option><option value="credit">Cartão de crédito</option><option value="transfer">Transferência</option><option value="installment">Parcelado</option><option value="other">Outro</option></select></label><label>Situação<select name="status" defaultValue={editing?.status||'received'}><option value="received">Recebido</option><option value="pending">Pendente</option></select></label><label>Vencimento<input type="date" name="due_at" defaultValue={editing?.due_at||''}/></label><label className="span2">Descrição do serviço / observação<input name="notes" defaultValue={editing?.notes||''}/></label><p className="form-hint span2">Se não vincular um orçamento, descreva o serviço aqui para constar no recibo. Não insira dados de cartão. O aplicativo registra somente o meio e o estado do pagamento.</p></div>}
{(modal==='service'||modal==='service-edit')&&<div className="form-grid"><label className="span2">Nome do serviço<input name="name" required defaultValue={editing?.name||''}/></label><label>Categoria<select name="category_id" defaultValue={editing?.category_id||''}><option value="">Selecione</option>{data.categories?.map(c=><option value={c.id}>{c.name}</option>)}</select></label><label>Código<input name="code" defaultValue={editing?.code||''}/></label><label>Unidade<select name="unit" defaultValue={editing?.unit||'service'}><option value="service">Serviço</option><option value="hour">Hora</option><option value="day">Diária</option><option value="meter">Metro</option><option value="unit">Unidade</option><option value="quantity">Quantidade</option></select></label><label>Preço padrão (R$)<input type="number" name="standard_price" min="0" step="0.01" placeholder="Opcional" defaultValue={editing?.standard_price??''}/></label><label>Custo estimado (R$)<input type="number" name="estimated_cost" min="0" step="0.01" defaultValue={editing?.estimated_cost??''}/></label><label>Prazo estimado<input name="estimated_duration" defaultValue={editing?.estimated_duration||''}/></label><label>Garantia<input name="warranty" defaultValue={editing?data.versions?.find(v=>v.quote_id===editing?.id&&v.version===editing.current_version)?.warranty||'':''}/></label><label className="span2">Descrição<textarea name="description" rows={2} defaultValue={editing?.description||''}/></label><label className="span2">Materiais necessários<textarea name="materials" rows={2} defaultValue={editing?.materials||''}/></label><p className="form-hint span2">O preço padrão é opcional; deixe vazio até definir o valor comercial do serviço.</p></div>}
{err&&<div className="error">{err}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>{setModal('');setEditing(null)}}>Cancelar</button><button disabled={busy} className="primary">{busy?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} Salvar</button></div></form></div>}</div>}
